  await next.evaluate(()=>{const b=PlayroomAppBridge,r=b.room();b.roomService.configure(r.id,r.ownerId,{firstPlayerMode:'assigned',firstParticipantId:r.ownerId});b.renderLobby();});
  phase='ready-and-start';for(const p of [host,other])await p.locator('[data-net-action=ready]').click();await next.locator('[data-command=lobby-ready]').click();await next.locator('[data-command=lobby-start]:not([disabled])').click();await next.locator('.table-shell.network-game').waitFor();await other.locator('.table-shell.network-game').waitFor();
